style.css:
@-moz-document domain("pinterest.com") {
/* FONDO DE LA PÁGINA: Celeste Pastel */
    body, html, #initial-focus-container, [data-test-id="grid"], .App, main {
        background-color: #B3E5FC !important;
    }

    /* ICONOS (Lupita, Casita, Inicio): Amarillo Pollito */
    svg, path, [role="img"], [data-test-id="navigation-bar"] svg, [data-test-id="search-box-search-icon"] svg {
        fill: #FFF59D !important;
        color: #FFF59D !important;
    }

    /* TEXTOS DE PUBLICACIONES: Blanco con sombra */
    h1, h2, h3, div, span, p, [data-test-id="pin-title"], [data-test-id="official-user-name"] {
        color: #FFFFFF !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.4) !important;
    }
}
